// Agente de revisão de conversas (07/10/2026): avalia as últimas 24 h e aponta erros do Dyno/Dina.
const d = $input.first().json || {};
const pessoas = Array.isArray(d.pessoas) ? d.pessoas : [];
const NL = String.fromCharCode(10);
if (!pessoas.length) return [{ json: { vazio: true, de: d.de, ate: d.ate } }];
// Limita o tamanho: no máximo 120 mensagens por pessoa e ~110k caracteres no total.
let total = 0;
const blocos = [];
for (const p of pessoas) {
  const conv = (p.conversa || []).slice(-120).map(m => m.h + ' ' + (m.quem === 'bot' ? 'BOT' : 'PESSOA') + ': ' + String(m.t || '').replace(/\s+/g, ' ')).join(NL);
  const cab = '### ' + p.nome + (p.familia ? ' (família, uso interno)' : ' (cliente' + (p.plano ? ', plano ' + p.plano : '') + (p.dias_de_uso != null ? ', ' + p.dias_de_uso + ' dias de uso' : '') + ')') + (p.grupo ? ' [grupo]' : '') + ' — ' + p.mensagens + ' mensagens';
  const b = cab + NL + conv;
  if (total + b.length > 110000) break;
  total += b.length; blocos.push(b);
}
const sistema = [
  'Você é o revisor de qualidade do Dyno e da Dina, assessores pessoais por WhatsApp (o Dyno cuida de dinheiro: gastos, contas, assinaturas; a Dina cuida de lembretes, tarefas, agenda e listas). O dono do produto, Daniel, lê seu relatório toda manhã para corrigir o assistente no mesmo dia.',
  'Você recebe as conversas das últimas 24 horas, uma por pessoa (PESSOA = quem fala; BOT = Dyno/Dina). Analise e devolva APENAS um JSON com este formato:',
  '{"resumo": "2 frases sobre o dia", "nota": 0-10, "achados": [{"pessoa": "nome", "gravidade": "alta|media|baixa", "tipo": "erro_de_registro|nao_entendeu|resposta_errada|nao_fez_o_pedido|repetiu_ou_insistiu_demais|tom_inadequado|frustracao_do_cliente|bug_tecnico|oportunidade", "hora": "DD/MM HH:MM", "o_que_aconteceu": "1 frase objetiva", "evidencia": "trecho curto literal", "correcao_sugerida": "1 frase prática"}], "destaques_positivos": ["..."], "pedidos_nao_atendidos": ["função ou pedido que o assistente não sabe fazer e apareceu hoje"]}',
  'Regras: seja concreto e cite o trecho. Não invente. Ignore mensagens automáticas de rotina (bom dia, resumos, lembretes) a não ser que estejam erradas ou repetidas demais. Gravidade alta = dado gravado errado, pedido ignorado, cliente irritado ou bug visível. Máximo 12 achados, os mais importantes primeiro. Família é uso interno: avalie igual, mas marque. O nome no cabeçalho é o apelido da conta; se o BOT chamar a pessoa por outro nome, só aponte se a própria pessoa estranhar. Responda em português do Brasil, sem markdown fora do JSON.'
].join(NL);
const usuario = 'Período: ' + d.de + ' a ' + d.ate + '. Total: ' + d.total + ' mensagens de ' + d.total_pessoas + ' pessoas.' + NL + NL + blocos.join(NL + NL);
const payload = { model: 'gpt-5.6-luna', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }] };
return [{ json: { vazio: false, de: d.de, ate: d.ate, clientes: d.total_pessoas, mensagens: d.total, payload } }];

const r = $input.first().json || {};
const base = $('Montar pedido à IA').first().json;
const NL = String.fromCharCode(10), ZW = String.fromCharCode(8203);
let j = {};
try { j = JSON.parse(String(r.choices[0].message.content || '{}')); } catch (e) { j = { resumo: 'Não consegui interpretar a resposta da IA.', achados: [] }; }
const ach = Array.isArray(j.achados) ? j.achados : [];
const ic = { alta: '🔴', media: '🟠', baixa: '🟡' };
const dia = DateTime.now().setZone('America/Sao_Paulo').minus({ days: 1 }).toFormat('dd/LL');
const partes = ['🔎 *Revisão das conversas de ' + dia + '*', (j.resumo || '') + (j.nota != null ? ' Nota do dia: *' + j.nota + '/10*.' : ''), base.mensagens + ' mensagens de ' + base.clientes + ' pessoas.'];
const alta = ach.filter(a => a.gravidade === 'alta'), resto = ach.filter(a => a.gravidade !== 'alta');
const linha = a => (ic[a.gravidade] || '•') + ' *' + (a.pessoa || '?') + '* ' + (a.hora ? '(' + a.hora + ') ' : '') + (a.o_que_aconteceu || '') + (a.evidencia ? NL + '   _"' + String(a.evidencia).slice(0, 160) + '"_' : '') + (a.correcao_sugerida ? NL + '   → ' + a.correcao_sugerida : '');
if (alta.length) partes.push('*Precisa de ação:*' + NL + alta.map(linha).join(NL));
if (resto.length) partes.push('*Outros pontos:*' + NL + resto.slice(0, 8).map(linha).join(NL));
if (!ach.length) partes.push('✅ Nenhum erro relevante encontrado.');
if (Array.isArray(j.pedidos_nao_atendidos) && j.pedidos_nao_atendidos.length) partes.push('*Pedidos que o Dyno/Dina ainda não sabem fazer:*' + NL + j.pedidos_nao_atendidos.slice(0, 6).map(x => '• ' + x).join(NL));
if (Array.isArray(j.destaques_positivos) && j.destaques_positivos.length) partes.push('*Foi bem:* ' + j.destaques_positivos.slice(0, 3).join('; '));
let texto = partes.join(NL + NL);
if (texto.length > 6000) texto = texto.slice(0, 5980) + '…';
return [{ json: { texto, envio: { number: '5511930851325', text: ZW + texto, delay: 800 }, gravar: { p: { de: base.de, ate: base.ate, clientes: base.clientes, mensagens: base.mensagens, relatorio: texto, achados: j, modelo: r.model || 'gpt-5.6-luna' } }, uso: { p: { autor: 'Sistema', origem: 'revisao_diaria', tarefa: 'revisao', provedor: 'openai', modelo: r.model || 'gpt-5.6-luna', uso: r.usage || {} } } } }];
